package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/** A claim a person on a sheet makes: an amount (two decimals), a date, a note and a status (see
 * {@link ClaimStatus}). A claim with a negative amount is a correction of the SETTLED claim of the
 * same person whose number it names in {@link #corrects}. */
@Entity
@Table(name = "claim")
public class Claim {

    /** The kind of a proof that is a receipt, the kind a proof added without one is. */
    public static final String RECEIPT = "receipt";

    /** The kind of a proof that is a photo. */
    public static final String PHOTO = "photo";

    /** The kinds a proof may be, in the order they are offered. */
    public static final List<String> PROOF_KINDS = List.of(RECEIPT, PHOTO);

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    /** The date the claim is due by: the terms-th business day after its due-from (see
     * {@link net.officefloor.hq.app.holiday.HolidayService#dueBy}), skipping weekends and the sheet's
     * holidays; a holiday added later on or before it works it out again from its date while the claim is
     * not SETTLED or VOID. */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    /** The date the claim's due-by counts from: its date when it was added. Later changes to its date
     * leave it as it is. */
    @Column(name = "due_from", nullable = false)
    private LocalDate dueFrom;

    /** The terms, in business days, the claim was fixed with when it was added: those of its person, else
     * of their grade, else the sheet's, each in force on the day it was added (the sheet's today then). Later changes to the terms leave it. */
    @Column(name = "terms", nullable = false)
    private int terms;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** The claim's number on its sheet, given when it is opened and kept once VOID; null while
     * DRAFT (and on a claim voided as a draft). */
    @Column(name = "claim_number")
    private String number;

    /** What was due on the claim when it was settled; null until then, and when there was no rate. */
    @Column(name = "settled_due", precision = 12, scale = 2)
    private BigDecimal settledDue;

    /** The user who opened the claim; null until it is opened. */
    @Column(name = "opened_by")
    private String openedBy;

    /** The user who last edited the claim (its form or its amount); null while it was never edited. */
    @Column(name = "edited_by")
    private String editedBy;

    /** Whether the claim is bound to {@link #statedDue}, the figure it had at its person's last
     * statement that it counted in. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The figure the claim was bound to at its person's last statement; null while unbound, and when
     * it had no figure (no rate) then. */
    @Column(name = "stated_due", precision = 12, scale = 2)
    private BigDecimal statedDue;

    /** What was due on the claim as it showed when its last statement bound it, late charge and floor
     * included; null while unbound, when it had no figure then, and when it was bound before this was kept. */
    @Column(name = "stated_shown", precision = 12, scale = 2)
    private BigDecimal statedShown;

    /** The id of the statement that bound the claim; null while unbound. */
    @Column(name = "stated_by")
    private Long statedBy;

    /** The number of the SETTLED claim of the same person this correction corrects; null on a claim
     * that is not a correction. */
    @Column(name = "corrects")
    private String corrects;

    /** The claim's place in its sheet's list, newest (highest) first; given anew when it moves to
     * another person. */
    @Column(name = "listed", nullable = false)
    private long listed;

    /** When the claim was first added, as a claim id: the id of the claim it was cloned from (or that
     * one's), so that a clone takes the rates the original took; null when it is its own id. */
    @Column(name = "added")
    private Long added;

    /** The date the claim is deferred until; null when it was never deferred. While it is OPEN and the
     * sheet's today is before this date it is deferred (see {@link #isDeferredOn}). */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** How many proofs the claim has been given; raised by one at a time while it is neither SETTLED nor VOID. */
    @Column(name = "proofs", nullable = false)
    private int proofs;

    /** How many of the claim's proofs are photos; the rest are receipts. */
    @Column(name = "proofs_photo", nullable = false)
    private int proofsPhoto;

    /** The number of the claim this one was split off; null on a claim that was not split off another. */
    @Column(name = "split_from")
    private String splitFrom;

    /** Whether the claim was added while the period its due-by falls in was soft-closed. */
    @Column(name = "late_entry", nullable = false)
    private boolean lateEntry;

    /** The user whose open editor locks the claim for everyone else; null while no one holds it. */
    @Column(name = "locked_by")
    private String lockedBy;

    /** The sheet's today when {@link #lockedBy} took the lock: it holds only while that is still the
     * sheet's today. */
    @Column(name = "locked_on")
    private LocalDate lockedOn;

    /** The sheet's today on which a reminder of the claim was last written; null when none ever was. */
    @Column(name = "reminded_on")
    private LocalDate remindedOn;

    /** Whether a reminder of the claim has ever escalated it; it is escalated once at most. */
    @Column(name = "escalated", nullable = false)
    private boolean escalated;

    /** The claim's external reference; null when it has none. Unique on its sheet without regard to case. */
    @Column(name = "ref")
    private String ref;

    /** The reference as compared: lower-cased; null when there is none. */
    @Column(name = "ref_key")
    private String refKey;

    /** The claim's tags: trimmed, lower-cased, without repeats, sorted and comma separated; null when it
     * has none (see {@link #tagsOf}). */
    @Column(name = "tags")
    private String tags;

    /** The reason from its sheet's list the claim was voided with; null unless it was voided with one. */
    @Column(name = "void_reason")
    private String voidReason;

    /** The number of the bulk settle (batch) on its sheet that settled the claim (or left it PENDING); null
     * when it was settled one at a time, or not settled. */
    @Column(name = "settle_batch")
    private Integer settleBatch;

    /** Whether a steward waived the claim's late charge: it bears none from then on. */
    @Column(name = "waived", nullable = false)
    private boolean waived;

    /** Whether the claim is held; it still counts in every total. */
    @Column(name = "held", nullable = false)
    private boolean held;

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note, String corrects) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.corrects = corrects;
    }

    /** A copy of the claim for the person {@code personId} on the sheet {@code sheetId}: its amount,
     * dates, terms, note, status, frozen figure, opener and editor, deferral, proofs, tags and void reason
     * come with it; its number, any figure a statement bound, its reference, lock and settle batch do
     * not, nor what names other claims by number. */
    public Claim transferredTo(String sheetId, Long personId) {
        Claim copy = new Claim(sheetId, personId, amount, date, note, null);
        copy.dueBy = dueBy;
        copy.dueFrom = dueFrom;
        copy.terms = terms;
        copy.status = status;
        copy.settledDue = settledDue;
        copy.openedBy = openedBy;
        copy.editedBy = editedBy;
        copy.deferredUntil = deferredUntil;
        copy.proofs = proofs;
        copy.proofsPhoto = proofsPhoto;
        copy.lateEntry = lateEntry;
        copy.remindedOn = remindedOn;
        copy.escalated = escalated;
        copy.waived = waived;
        copy.held = held;
        copy.tags = tags;
        copy.voidReason = voidReason;
        return copy;
    }

    /** A copy of the claim for the person {@code personId} on the sheet {@code sheetId}, a clone of its
     * sheet: as {@link #transferredTo} makes it, with its reference too; its number, and what names other
     * claims by number, are given by the clone. */
    public Claim clonedTo(String sheetId, Long personId) {
        Claim copy = transferredTo(sheetId, personId);
        copy.setRef(ref);
        copy.added = addedMark();
        return copy;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public long getListed() {
        return listed;
    }

    public void setListed(long listed) {
        this.listed = listed;
    }

    /** When the claim was first added, as a claim id (see {@link net.officefloor.hq.app.rate.Rate#forClaim});
     * the highest there is when it is not yet saved. */
    public long addedMark() {
        return added != null ? added : id != null ? id : Long.MAX_VALUE;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public LocalDate getDueBy() {
        return dueBy;
    }

    public void setDueBy(LocalDate dueBy) {
        this.dueBy = dueBy;
    }

    public LocalDate getDueFrom() {
        return dueFrom;
    }

    public int getTerms() {
        return terms;
    }

    /** Fix the date the claim's due-by counts from and the terms it is due by. */
    public void fixTerms(LocalDate dueFrom, int terms) {
        this.dueFrom = dueFrom;
        this.terms = terms;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    public boolean isStated() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    public BigDecimal getStatedShown() {
        return statedShown;
    }

    public Long getStatedBy() {
        return statedBy;
    }

    /** Bind the claim to {@code due}, the figure it has now, and {@code shown}, what is due on it as it
     * shows now (late charge and floor included), by the statement {@code statementId}. */
    public void bind(BigDecimal due, BigDecimal shown, Long statementId) {
        this.stated = true;
        this.statedDue = due;
        this.statedShown = shown;
        this.statedBy = statementId;
    }

    /** Leave the claim unbound: its figure follows the rates again. */
    public void unbind() {
        this.stated = false;
        this.statedDue = null;
        this.statedShown = null;
        this.statedBy = null;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public String getEditedBy() {
        return editedBy;
    }

    public void setEditedBy(String editedBy) {
        this.editedBy = editedBy;
    }

    /** Whether {@code user} opened or last edited the claim: they may not settle or approve it. */
    public boolean isOpenedOrEditedBy(String user) {
        return user.equals(openedBy) || user.equals(editedBy);
    }

    public String getCorrects() {
        return corrects;
    }

    public void setCorrects(String corrects) {
        this.corrects = corrects;
    }

    /** Whether the claim is a correction: one with a negative amount. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    public boolean isLateEntry() {
        return lateEntry;
    }

    public void setLateEntry(boolean lateEntry) {
        this.lateEntry = lateEntry;
    }

    public String getSplitFrom() {
        return splitFrom;
    }

    public void setSplitFrom(String splitFrom) {
        this.splitFrom = splitFrom;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    public void setDeferredUntil(LocalDate deferredUntil) {
        this.deferredUntil = deferredUntil;
    }

    public boolean isEscalated() {
        return escalated;
    }

    public void setEscalated(boolean escalated) {
        this.escalated = escalated;
    }

    public LocalDate getRemindedOn() {
        return remindedOn;
    }

    public void setRemindedOn(LocalDate remindedOn) {
        this.remindedOn = remindedOn;
    }

    public int getProofs() {
        return proofs;
    }

    /** How many of the claim's proofs are of {@code kind} (receipt or photo). */
    public int getProofsOf(String kind) {
        return PHOTO.equals(kind) ? proofsPhoto : RECEIPT.equals(kind) ? proofs - proofsPhoto : 0;
    }

    /** Raise the claim's proofs count by one, a proof of {@code kind} (receipt or photo). */
    public void addProof(String kind) {
        this.proofs++;
        if (PHOTO.equals(kind)) this.proofsPhoto++;
    }

    /** Whether the claim is deferred on {@code today}: OPEN and deferred until a date after it. */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }

    /** Whether a user other than {@code user} holds the claim's lock on {@code today}. */
    public boolean isLockedFor(String user, LocalDate today) {
        return lockedBy != null && !lockedBy.equals(user) && today.equals(lockedOn);
    }

    /** Lock the claim for everyone but {@code user} while {@code today} is the sheet's today. */
    public void lock(String user, LocalDate today) {
        this.lockedBy = user;
        this.lockedOn = today;
    }

    /** Release the claim's lock, whoever holds it. */
    public void unlock() {
        this.lockedBy = null;
        this.lockedOn = null;
    }

    public String getVoidReason() {
        return voidReason;
    }

    public void setVoidReason(String voidReason) {
        this.voidReason = voidReason;
    }

    public String getRef() {
        return ref;
    }

    /** Give the claim the external reference {@code ref}, or none when null. */
    public void setRef(String ref) {
        this.ref = ref;
        this.refKey = keyOf(ref);
    }

    /** A reference as compared: lower-cased; null for none. */
    public static String keyOf(String ref) {
        return ref == null ? null : ref.toLowerCase(java.util.Locale.ROOT);
    }

    /** The claim's tags, sorted; empty when it has none. */
    public java.util.List<String> getTags() {
        return tags == null ? java.util.List.of() : java.util.List.of(tags.split(","));
    }

    /** Give the claim the tags, as {@link #tagsOf} makes them (none when null). */
    public void setTags(String tags) {
        this.tags = tags;
    }

    /** Tags as kept from comma separated text: each trimmed and lower-cased, blanks and repeats dropped,
     * sorted and comma separated; null when there are none. */
    public static String tagsOf(String text) {
        if (text == null) return null;
        java.util.TreeSet<String> tags = new java.util.TreeSet<>();
        for (String tag : text.split(",")) {
            String t = tag.trim().toLowerCase(java.util.Locale.ROOT);
            if (!t.isEmpty()) tags.add(t);
        }
        return tags.isEmpty() ? null : String.join(",", tags);
    }

    public String getLockedBy() {
        return lockedBy;
    }

    public Integer getSettleBatch() {
        return settleBatch;
    }

    public void setSettleBatch(Integer settleBatch) {
        this.settleBatch = settleBatch;
    }

    public boolean isWaived() {
        return waived;
    }

    /** Waive the claim's late charge. */
    public void waive() {
        this.waived = true;
    }

    public boolean isHeld() {
        return held;
    }

    public void setHeld(boolean held) {
        this.held = held;
    }
}
package net.officefloor.hq.app.claim;

import java.util.Set;

/** Where a claim is in its life: added as a draft, opened, then settled. A clerk's settle of a claim
 * whose due is above the clerk limit leaves it PENDING until a steward approves it (SETTLED) or rejects
 * it (back to OPEN). A draft, open or pending claim can be voided, and a settled one by a steward
 * within 7 days of its settlement. A voided claim cannot change status. A draft can be DELETED, and a
 * deleted claim made a DRAFT again (restored) on the same sheet-today it was deleted. A claim opened while its
 * due is above the review threshold in force on its date goes to REVIEW instead of OPEN, counting nowhere,
 * until a steward reviews it (OPEN); a claim in REVIEW can also be voided. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** Whether a claim in this status counts toward what its person has claimed and is due. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether a claim in this status is still open: OPEN, or PENDING, which is handled like OPEN
     * (it goes overdue, bears the late charge). */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status may move to {@code next}. */
    public boolean canBecome(ClaimStatus next) {
        return switch (this) {
            case DRAFT -> Set.of(OPEN, VOID, DELETED, REVIEW).contains(next);
            case REVIEW -> Set.of(OPEN, VOID).contains(next);
            case OPEN -> Set.of(PENDING, SETTLED, VOID).contains(next);
            case PENDING -> Set.of(OPEN, SETTLED, VOID).contains(next);
            case SETTLED -> next == VOID;
            case VOID -> false;
            case DELETED -> next == DRAFT;
        };
    }
}

