350	    /** Part-settle an OPEN claim: split {@code amount} off it as {@link #split} does, then settle the new
351	     * claim as {@link #changeStatus(String, String, long, ClaimStatus)} does (left PENDING when the clerk
352	     * limit says so). Who may settle and the proof rule are judged on the claim as it was before the split,
353	     * so the user, who opens the new claim, may still settle it. Refused, changing nothing, when the split
354	     * or the settle would be. Both claims are returned, the original first. */
355	    @Transactional
356	    public List<Claim> partSettle(String sheetId, String user, long claimId, BigDecimal amount) {
357	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
358	        if (!settings.allowed(sheetId, user, Action.SETTLE)) throw new ClaimNotStewardException();
359	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
360	            throw new ClaimStatusChangeException();
361	        }
362	        if (claim.isOpenedOrEditedBy(user)) throw new ClaimSelfSettleException();
363	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
364	                .orElseThrow(PersonNotFoundException::new);
365	        refuseUnproved(claim, person, rollup.shownOf(claim, person));
366	        List<Claim> split = split(sheetId, user, claimId, amount);
367	        Claim settled = changeStatus(sheetId, user, split.get(1).getId(), ClaimStatus.SETTLED, null, true, null);
368	        return List.of(split.get(0), settled);
369	    }
370	
371	    /** Move the claim to {@code next}; with {@code judged}, who may settle it and the proof rule have
372	     * already been judged (on the claim a part-settle split it from); a settle with {@code on} is as of
373	     * that date (see {@link #settle}). */
374	    private Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next, String voidReason,
375	            boolean judged, LocalDate on) {
376	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
377	        Action action = switch (next) {
378	            case OPEN -> Action.OPEN;
379	            case SETTLED -> Action.SETTLE;
380	            case VOID -> Action.VOID;
381	            default -> null;
382	        };
383	        if (action != null && !settings.allowed(sheetId, user, action)) throw new ClaimNotStewardException();
384	        refuseClosed(sheetId, claim.getDueBy());
385	        if (!claim.getStatus().canBecome(next)
386	                || ((claim.getStatus() == ClaimStatus.PENDING || claim.getStatus() == ClaimStatus.REVIEW) && next != ClaimStatus.VOID)) {
387	            throw new ClaimStatusChangeException();
388	        }
389	        boolean reversing = claim.getStatus() == ClaimStatus.SETTLED;
390	        if (reversing) refuseLateVoid(sheetId, user, claim);
391	        String reason = next == ClaimStatus.VOID ? voidReasons.refuseUnlisted(sheetId, voidReason) : null;
392	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimStatusChangeException();
393	        if (next == ClaimStatus.SETTLED && !judged && claim.isOpenedOrEditedBy(user)) throw new ClaimSelfSettleException();
394	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
395	                .orElseThrow(PersonNotFoundException::new);
396	        if (next == ClaimStatus.OPEN && person.isFlaggedOn(sheets.today(sheetId))
397	                && settings.roleOf(sheetId, user) != Role.STEWARD) {
398	            throw new ClaimNotStewardException();
399	        }
400	        if (next == ClaimStatus.OPEN) refuseNoteless(claim, rollup.shownOf(claim, person));
401	        if (next == ClaimStatus.OPEN) refuseOverCap(sheetId, claim);
402	        RollupService.Snapshot before = rollup.snapshot(sheetId);
403	        String number = claim.getNumber();
404	        if (next == ClaimStatus.OPEN && overReview(claim, person)) {
405	            next = ClaimStatus.REVIEW;
406	            claim.setOpenedBy(user);
407	        } else if (next == ClaimStatus.OPEN) {
408	            number = nextNumber(sheetId, claim.getDueBy());
409	            claim.setOpenedBy(user);
410	        }
411	        BigDecimal dueThen = null;
412	        if (next == ClaimStatus.SETTLED && on != null) {
413	            if (on.isAfter(sheets.today(sheetId))) throw new ClaimSettleDateException();
414	            SheetAsOf then = history.asOf(sheetId, on);
415	            Claim stood = then.claims().stream().filter(c -> c.getId().equals(claim.getId())).findFirst()
416	                    .orElseThrow(ClaimSettleDateException::new);
417	            Person personThen = then.person(person.getId()).orElseThrow(ClaimSettleDateException::new);
418	            dueThen = rollup.shownOf(stood, personThen, then);
419	        }
420	        if (next == ClaimStatus.SETTLED) {
421	            BigDecimal due = on == null ? rollup.shownOf(claim, person) : dueThen;
422	            if (!judged) refuseUnproved(claim, person, due);
423	            if (overLimit(sheetId, user, person, due)) next = ClaimStatus.PENDING;
424	            else claim.setSettledDue(due);
425	        }
426	        claim.setStatus(next);
427	        claim.setNumber(number);
428	        if (next == ClaimStatus.VOID) claim.setVoidReason(reason);
429	        claims.flush();
430	        log(user, person, claim);
431	        String event = switch (next) {
432	            case OPEN -> "CLAIM_OPENED";
433	            case REVIEW -> "CLAIM_REVIEW";
434	            case PENDING -> "CLAIM_PENDING";
435	            case SETTLED -> "CLAIM_SETTLED";
436	            case VOID -> "CLAIM_VOIDED";
437	            case DRAFT, DELETED -> throw new IllegalStateException();
438	        };
439	        if (next == ClaimStatus.SETTLED) {
440	            List<String> extra = new ArrayList<>(List.of("due=" + dueText(claim.getSettledDue())));
441	            if (on != null) extra.add("on=" + on);
442	            record(event, user, person, claim, number, extra.toArray(String[]::new));
443	            notifyWatchers(user, person, claim);
444	        } else {
445	            List<String> extra = new ArrayList<>();
446	            if (reversing) extra.add("reversed=" + dueText(claim.getSettledDue()));
447	            if (reason != null) extra.add("reason=" + reason);
448	            record(event, user, person, claim, number, extra.toArray(String[]::new));
449	        }
450	        rollup.recordSince(sheetId, user, before);
451	        return claim;
452	    }
