555	    /** Remind an OPEN or PENDING claim: a reminder is written and the claim is reminded on the sheet's
556	     * today. Refused unless the claim is OPEN or PENDING, when it was already reminded on the sheet's
557	     * today, and when its due-by is in a closed period. A claim not yet escalated whose previous reminder was
558	     * at least the sheet's escalation gap before the sheet's today is escalated too, written after the reminder. */
559	    @Transactional
560	    public Claim remind(String sheetId, String user, long claimId) {
561	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
562	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
563	            throw new ClaimStatusChangeException();
564	        }
565	        LocalDate today = sheets.today(sheetId);
566	        if (today.equals(claim.getRemindedOn())) throw new ClaimRemindedException();
567	        refuseClosed(sheetId, claim.getDueBy());
568	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
569	                .orElseThrow(PersonNotFoundException::new);
570	        Integer gap = settings.escalateAfter(sheetId);
571	        LocalDate previous = claim.getRemindedOn();
572	        boolean escalate = gap != null && previous != null && !claim.isEscalated()
573	                && !previous.plusDays(gap).isAfter(today);
574	        claim.setRemindedOn(today);
575	        if (escalate) claim.setEscalated(true);
576	        claims.flush();
577	        record("REMIND", user, person, claim, claim.getNumber());
578	        if (escalate) record("ESCALATE", user, person, claim, claim.getNumber());
579	        return claim;
580	    }
