606	    /** Split {@code amount} (more than 0.00 and less than the claim's amount) off an OPEN claim: the
607	     * claim keeps the rest and loses any figure a statement bound it to; a new OPEN claim of the split-off
608	     * amount, with the same person, date and note, is given the next number, is opened by the user, has
609	     * its due-by fixed now from its date and the terms in force on the sheet's today and names the claim's number as the one
610	     * it was split from; it is a late entry when that due-by falls in a soft-closed period. Refused unless
611	     * the claim is OPEN and not deferred on the sheet's today, and when its due-by or the new claim's falls
612	     * in a closed period. Both claims are returned, the original first. */
613	    @Transactional
614	    public List<Claim> split(String sheetId, String user, long claimId, BigDecimal amount) {
615	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
616	        refuseClosed(sheetId, claim.getDueBy());
617	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
618	            throw new ClaimStatusChangeException();
619	        }
620	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) throw new ClaimSplitException();
621	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
622	                .orElseThrow(PersonNotFoundException::new);
623	        RollupService.Snapshot before = rollup.snapshot(sheetId);
624	        claim.setAmount(claim.getAmount().subtract(amount));
625	        claim.unbind();
626	        Claim split = new Claim(sheetId, person.getId(), amount, claim.getDate(), claim.getNote(), null);
627	        int terms = termsOf(sheetId, person, sheets.today(sheetId));
628	        split.fixTerms(claim.getDate(), terms);
629	        split.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
630	        refuseClosed(sheetId, split.getDueBy());
631	        split.setLateEntry(periods.softClosedOn(sheetId, split.getDueBy()));
632	        split.setListed(sheets.nextInSequence(sheetId, "listed"));
633	        split.setStatus(ClaimStatus.OPEN);
634	        split.setNumber(nextNumber(sheetId, split.getDueBy()));
635	        split.setOpenedBy(user);
636	        split.setSplitFrom(claim.getNumber());
637	        split.setTags(claim.getTags().isEmpty() ? null : String.join(",", claim.getTags()));
638	        split = claims.saveAndFlush(split);
639	        log(user, person, split);
640	        record("CLAIM_SPLIT", user, person, claim, claim.getNumber(), "into=" + split.getNumber());
641	        record("CLAIM_OPENED", user, person, split, split.getNumber());
642	        rollup.recordSince(sheetId, user, before);
643	        return List.of(claim, split);
644	    }
645	
646	    /** A steward's review of a claim in REVIEW: it becomes OPEN and is given the next number then,
647	     * keeping who opened it. Refused unless the claim is in REVIEW, when the user is not a steward, and
648	     * when its due-by is in a closed period. */
649	    @Transactional
650	    public Claim review(String sheetId, String user, long claimId) {
651	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
652	        refuseClosed(sheetId, claim.getDueBy());
653	        if (claim.getStatus() != ClaimStatus.REVIEW) throw new ClaimStatusChangeException();
654	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
655	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
656	                .orElseThrow(PersonNotFoundException::new);
657	        RollupService.Snapshot before = rollup.snapshot(sheetId);
658	        String number = nextNumber(sheetId, claim.getDueBy());
659	        claim.setStatus(ClaimStatus.OPEN);
660	        claim.setNumber(number);
661	        claims.flush();
662	        log(user, person, claim);
663	        record("CLAIM_REVIEWED", user, person, claim, null);
664	        record("CLAIM_OPENED", user, person, claim, number);
665	        rollup.recordSince(sheetId, user, before);
666	        return claim;
667	    }
668	
669	    /** A steward's (or the person's approver's) approval of a PENDING claim: it becomes SETTLED, fixing what is due on it then (as it
670	     * shows then: what a statement bound it to, late charge included, when one did, otherwise its person's rate then together with its late charge then).
671	     * Refused unless the claim is PENDING, when the user is not a steward or opened or last edited the claim, and when it
672	     * has no proofs and that due is above the proof threshold in force on its date. */
673	    @Transactional
674	    public Claim approve(String sheetId, String user, long claimId) {
675	        Claim claim = lockPending(sheetId, user, claimId);
676	        if (claim.isOpenedOrEditedBy(user)) throw new ClaimNotStewardException();
677	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
678	                .orElseThrow(PersonNotFoundException::new);
679	        RollupService.Snapshot before = rollup.snapshot(sheetId);
680	        BigDecimal due = rollup.shownOf(claim, person);
681	        refuseUnproved(claim, person, due);
682	        claim.setSettledDue(due);
683	        claim.setStatus(ClaimStatus.SETTLED);
684	        claims.flush();
685	        log(user, person, claim);
686	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), "due=" + dueText(due));
687	        notifyWatchers(user, person, claim);
688	        rollup.recordSince(sheetId, user, before);
689	        return claim;
690	    }
691	
692	    /** Raise the claim's proofs count by one, a proof of {@code kind} (receipt or photo; a receipt when
693	     * null, and the audit record then names no kind). Refused when the claim is SETTLED or VOID; a proof leaves
694	     * the claim's figures alone, so it may be added while the claim is dated in a closed period. */
695	    @Transactional
696	    public Claim addProof(String sheetId, String user, long claimId, String kind) {
697	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
698	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
699	                || claim.getStatus() == ClaimStatus.DELETED) {
700	            throw new ClaimStatusChangeException();
701	        }
702	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
703	                .orElseThrow(PersonNotFoundException::new);
704	        claim.addProof(kind == null ? Claim.RECEIPT : kind);
705	        claims.flush();
706	        if (kind == null) {
707	            record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), "proofs=" + claim.getProofs());
708	        } else {
709	            record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), "proofs=" + claim.getProofs(), "kind=" + kind);
710	        }
711	        return claim;
712	    }
713	
714	    /** A steward's (or the person's approver's) rejection of a PENDING claim, for {@code reason}: it goes back to OPEN, bound again
715	     * by its person's last statement if that statement included it. Refused unless the claim is
716	     * PENDING, and when the user is not a steward. */
717	    @Transactional
718	    public Claim reject(String sheetId, String user, long claimId, String reason) {
719	        Claim claim = lockPending(sheetId, user, claimId);
720	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
721	                .orElseThrow(PersonNotFoundException::new);
722	        RollupService.Snapshot before = rollup.snapshot(sheetId);
723	        claim.setStatus(ClaimStatus.OPEN);
724	        claims.flush();
725	        log(user, person, claim);
726	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), "reason=" + reason);
727	        rollup.recordSince(sheetId, user, before);
728	        return claim;
729	    }
730	
731	    /** A move, by a role the permission matrix allows to reassign (a steward by default), of a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
732	     * date but, unless a draft (which has no number), is given the next number in the sequence it is
733	     * numbered in (as when opened now), its old number never used again; it loses
734	     * any figure a statement bound it to (it is live again until its new person's next statement), and is listed as its new person's newest claim. Refused when the user's
735	     * role may not reassign, when the claim is SETTLED or VOID, is a correction (it corrects a claim of its
736	     * own person) or already belongs to the person, when it is due by in a closed period, and when it
737	     * is dated after the new person's retirement date. */
738	    @Transactional
739	    public Claim reassign(String sheetId, String user, long claimId, long personId) {
740	        return move(sheetId, user, claimId, personId, false);
741	    }
742	
743	    /** A move of one of several claims moved together: by the rules of {@link #reassign}, except that a
744	     * claim that already belongs to the person goes through (it is listed as the person's newest claim,
745	     * and recorded). */
746	    @Transactional
747	    public Claim reassignOfBulk(String sheetId, String user, long claimId, long personId) {
748	        return move(sheetId, user, claimId, personId, true);
749	    }
750	
751	    private Claim move(String sheetId, String user, long claimId, long personId, boolean samePerson) {
752	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
753	        if (!settings.allowed(sheetId, user, Action.REASSIGN)) throw new ClaimNotStewardException();
754	        refuseClosed(sheetId, claim.getDueBy());
755	        ClaimStatus status = claim.getStatus();
756	        if ((status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING)
757	                || claim.isCorrection() || (!samePerson && claim.getPersonId() == personId)) {
758	            throw new ClaimReassignException();
759	        }
760	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
761	                .orElseThrow(PersonNotFoundException::new);
762	        Person to = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
763	        to.requireClaimable(claim.getDate());
764	        RollupService.Snapshot before = rollup.snapshot(sheetId);
765	        claim.setPersonId(to.getId());
766	        claim.unbind();
767	        if (claim.getNumber() != null) claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
768	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
769	        claims.flush();
770	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(), "from=" + from.getName(), "to=" + to.getName());
771	        rollup.recordSince(sheetId, user, before);
772	        return claim;
773	    }
774	
775	    /** A steward's re-settle of a SETTLED claim: it is fixed again at what would be due on it now were
776	     * it OPEN and bound by no statement (its person's rate and grade, the sheet's floor and its late
777	     * charge, all as they are now). Refused unless the claim is SETTLED, when the user is not a
778	     * steward, and when it is dated in a closed period. */
779	    @Transactional
780	    public Claim resettle(String sheetId, String user, long claimId) {
781	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
782	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
783	        refuseClosed(sheetId, claim.getDueBy());
784	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusChangeException();
785	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
786	                .orElseThrow(PersonNotFoundException::new);
787	        RollupService.Snapshot before = rollup.snapshot(sheetId);
788	        BigDecimal old = claim.getSettledDue();
789	        BigDecimal due = rollup.openShownOf(claim, person);
790	        claim.setSettledDue(due);
791	        claims.flush();
792	        log(user, person, claim);
793	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(), "old=" + dueText(old), "new=" + dueText(due));
794	        notifyWatchers(user, person, claim);
795	        rollup.recordSince(sheetId, user, before);
796	        return claim;
797	    }
798	
799	    /** Refuse a void of the SETTLED claim unless the user is a steward and the sheet's today is at most
800	     * 7 days after the date its status log first shows it SETTLED. */
801	    private void refuseLateVoid(String sheetId, String user, Claim claim) {
802	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
803	        LocalDate settled = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
804	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
805	                .map(ClaimLog::getDate)
806	                .findFirst()
807	                .orElseThrow(ClaimStatusChangeException::new);
808	        if (sheets.today(sheetId).isAfter(settled.plusDays(7))) throw new ClaimVoidLateException();
809	    }
810	
811	    /** The PENDING claim, locked, for a steward or its person's approver to approve or reject. */
812	    private Claim lockPending(String sheetId, String user, long claimId) {
813	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
814	        refuseClosed(sheetId, claim.getDueBy());
815	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusChangeException();
816	        if (settings.roleOf(sheetId, user) != Role.STEWARD && !isApprover(sheetId, user, claim)) {
817	            throw new ClaimNotStewardException();
818	        }
819	        return claim;
820	    }
821	
822	    /** Whether {@code user} is the approver of the claim's person. */
823	    private boolean isApprover(String sheetId, String user, Claim claim) {
824	        return people.findByIdAndSheetId(claim.getPersonId(), sheetId)
825	                .map(Person::getApprover)
826	                .filter(user::equals)
827	                .isPresent();
828	    }
829	
830	    private static String dueText(BigDecimal due) {
831	        return due == null ? "n/a" : due.toPlainString();
832	    }
833	
834	    /** The figure the claim shows and totals now, without its late charge or floor; null when it has no figure
835	     * (see {@link RollupService#figureOf}). */
836	    public BigDecimal figureOf(Claim claim, Person person) {
837	        return rollup.figureOf(claim, person);
838	    }
839	
840	    /** What is due on the claim as it shows and totals now, its late charge included; null when it has
841	     * no figure (see {@link RollupService#shownOf}). */
842	    public BigDecimal shownOf(Claim claim, Person person) {
843	        return rollup.shownOf(claim, person);
844	    }
845	
846	    /** Keep each of the claim's tags among those ever used on its sheet. */
847	    public void keepTags(Claim claim) {
848	        for (String tag : claim.getTags()) {
849	            SheetTag.Key key = new SheetTag.Key(claim.getSheetId(), tag);
850	            if (!tagRepository.existsById(key)) tagRepository.save(new SheetTag(claim.getSheetId(), tag));
851	        }
852	    }
853	
854	    /** Write the status the claim has now to its log, with the sheet's today and what is due on it as
855	     * it shows now. */
856	    private void log(String user, Person person, Claim claim) {
857	        logs.save(new ClaimLog(claim.getId(), claim.getStatus(), user, sheets.today(claim.getSheetId()),
858	                rollup.shownOf(claim, person)));
859	    }
860	
861	    /** Record a change to the claim; {@code number}, the number it has (or had), follows when there is one,
862	     * then any {@code extra} fields. */
863	    private void record(String event, String user, Person person, Claim claim, String number, String... extra) {
864	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
865	                "amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
866	                "date=" + claim.getDate()));
867	        if (number != null) fields.add("number=" + number);
868	        fields.addAll(List.of(extra));
869	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
870	    }
871	
872	    /** Notify each user watching the person, in the order they started watching, that the claim was
873	     * settled, approved or re-settled. */
874	    private void notifyWatchers(String user, Person person, Claim claim) {
875	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
876	            audit.change("NOTIFY", claim.getSheetId(), user, "user=" + watch.getUser(), "person=" + person.getName(),
877	                    "number=" + claim.getNumber());
878	        }
879	    }
880	
881	    /** The number a claim due by {@code date} is given when opened now: within the period containing
882	     * that date ({@code <period name>-<n>}, or {@code X-<n>} when none does) while the sheet numbers by
883	     * period, otherwise the next sheet-wide number in the fiscal year of that date ({@code FY<yyyy>-<n>}). */
884	    public String nextNumber(String sheetId, LocalDate date) {
885	        if (!sheets.numbersByPeriod(sheetId)) return sheets.nextClaimNumber(sheetId, date);
886	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
887	                .filter(p -> !date.isBefore(p.getFrom()) && !date.isAfter(p.getTo()))
888	                .findFirst()
889	                .map(p -> p.getName() + "-" + sheets.nextInSequence(sheetId, "period:" + p.getId()))
890	                .orElseGet(() -> "X-" + sheets.nextInSequence(sheetId, "none"));
891	    }
892	
893	    /** Whether a settle by {@code user} of a claim whose due is {@code due} needs a steward's approval:
894	     * the user is a clerk and the due is above the clerk limit in force on the sheet's today (the person's
895	     * grade's own then, else the sheet's). */
896	    private boolean overLimit(String sheetId, String user, Person person, BigDecimal due) {
897	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
898	        BigDecimal limit = settings.clerkLimitFor(sheetId, person.gradeOn(sheets.today(sheetId)));
899	        return limit != null && due.compareTo(limit) > 0;
900	    }
901	
902	    /** Refuse a settle or approval of the claim, whose due is {@code due}, when that due is above the proof
903	     * threshold in force on its date (its person's grade's own then, else the sheet's; a due that is n/a is
904	     * within any threshold) while it has no proofs, or, while the sheet lists proof kinds, no proof of one
905	     * of them. */
906	    private void refuseUnproved(Claim claim, Person person, BigDecimal due) {
907	        if (due == null) return;
908	        String kinds = settings.proofKinds(claim.getSheetId());
909	        boolean proved = claim.getProofs() > 0 && (kinds == null
910	                || Arrays.stream(kinds.split(",")).allMatch(kind -> claim.getProofsOf(kind) > 0));
911	        if (proved) return;
912	        BigDecimal threshold = settings.proofThresholdFor(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
913	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
914	    }
915	
916	    /** Whether an open of the claim goes to REVIEW: its due as it shows now is above the review threshold
917	     * in force on its date (a due that is n/a is within any threshold). */
918	    private boolean overReview(Claim claim, Person person) {
919	        BigDecimal due = rollup.shownOf(claim, person);
920	        if (due == null) return false;
921	        BigDecimal threshold = settings.reviewThresholdOn(claim.getSheetId(), claim.getDate());
922	        return threshold != null && due.compareTo(threshold) > 0;
923	    }
924	
925	    /** Refuse an open of the claim, whose due is {@code due}, while its note is empty and that due is
926	     * above the note threshold in force on its date (a due that is n/a is within any threshold). */
927	    private void refuseNoteless(Claim claim, BigDecimal due) {
928	        if (due == null || !noteOf(claim.getNote()).isEmpty()) return;
929	        BigDecimal threshold = settings.noteThresholdOn(claim.getSheetId(), claim.getDate());
930	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimNoteRequiredException();
931	    }
932	
933	    /** Refuse a correction (a negative {@code amount}) that does not name, by number, a SETTLED claim of
934	     * the person, or that exceeds what remains of it: its amount less the corrections already made
935	     * against it (other than {@code claimId}, the one being edited; VOID and DELETED ones left out); and
936	     * a claim that names one without being a correction. */
937	    private void refuseBadCorrection(String sheetId, Long personId, Long claimId, BigDecimal amount,
938	            String corrects) {
939	        if (amount.signum() >= 0) {
940	            if (corrects != null) throw new ClaimCorrectionException();
941	            return;
942	        }
943	        if (corrects == null) throw new ClaimCorrectionException();
944	        Claim corrected = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
945	                .filter(target -> target.getStatus() == ClaimStatus.SETTLED)
946	                .orElseThrow(ClaimCorrectionException::new);
947	        BigDecimal remains = corrected.getAmount();
948	        for (Claim made : claims.findBySheetIdAndPersonIdAndCorrects(sheetId, personId, corrects)) {
949	            if (made.getId().equals(claimId) || made.getStatus() == ClaimStatus.VOID
950	                    || made.getStatus() == ClaimStatus.DELETED) continue;
951	            remains = remains.add(made.getAmount());
952	        }
953	        if (amount.negate().compareTo(remains) > 0) throw new ClaimCorrectionException();
954	    }
955	
956	    /** Refuse the external reference {@code ref} when a claim on the sheet other than {@code claimId} has
957	     * it, compared without regard to case. */
958	    private void refuseRefTaken(String sheetId, Long claimId, String ref) {
959	        if (ref == null) return;
960	        claims.findBySheetIdAndRefKey(sheetId, Claim.keyOf(ref))
961	                .filter(other -> !other.getId().equals(claimId))
962	                .ifPresent(other -> {
963	                    throw new ClaimRefTakenException();
964	                });
965	    }
966	
967	    /** Refuse opening the claim when the period its due-by falls in caps its person's OPEN or PENDING
968	     * claims in it, and they already have that many. The period is locked until the transaction ends,
969	     * so two claims are never opened past its cap at once. */
970	    private void refuseOverCap(String sheetId, Claim claim) {
971	        LocalDate dueBy = claim.getDueBy();
972	        Period capped = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
973	                .filter(p -> p.getCap() != null && p.overlaps(dueBy, dueBy)).findFirst().orElse(null);
974	        if (capped == null) return;
975	        Period period = periods.lockByIdAndSheetId(capped.getId(), sheetId).orElseThrow();
976	        long open = claims.findBySheetIdOrderByListedDescIdDesc(sheetId).stream()
977	                .filter(c -> !c.getId().equals(claim.getId()) && c.getPersonId().equals(claim.getPersonId())
978	                        && c.getStatus().isOpen() && c.getDueBy() != null && period.overlaps(c.getDueBy(), c.getDueBy()))
979	                .count();
980	        if (open >= period.getCap()) throw new ClaimCapException();
981	    }
982	
983	    /** Refuse a change to a claim due by {@code date} when a closed period of the sheet contains it. */
984	    private void refuseClosed(String sheetId, LocalDate date) {
985	        if (periods.closedOn(sheetId, date)) throw new ClaimPeriodClosedException();
986	    }
987	
988	    private static String noteOf(String note) {
989	        return note == null ? "" : note.trim();
990	    }
991	
992	    /** The terms a claim of the person created on {@code date} (the sheet's today then) is due by: the person's own terms
993	     * in force on that day, else those of their grade in force on that day, else the sheet's then. */
994	    private int termsOf(String sheetId, Person person, LocalDate date) {
995	        Integer own = person.termsOn(date);
996	        return own != null ? own : settings.termsFor(sheetId, person.gradeOn(date), date);
997	    }
998	}
