25	import net.officefloor.hq.app.sheet.SheetRepository;
26	import org.springframework.stereotype.Service;
27	import org.springframework.transaction.annotation.Propagation;
28	import org.springframework.transaction.annotation.Transactional;
29	
30	/**
31	 * The figures each person on a sheet shows — what they have claimed (their OPEN, PENDING and SETTLED
32	 * claims that are not corrections, leaving out the OPEN ones deferred on the sheet's today, and the OPEN and PENDING
33	 * ones once their retirement date is reached on the sheet's today that no statement binds; a hold leaves them in)
34	 * and their due-total (the sum of what is due on the claims that count live as each shows it, n/a when none has a figure and no rate of
35	 * their grade is in force on the sheet's today, and at most the sheet's cap in force on its today when it has one) and their
36	 * overdue-total (the sum of what is due on those that are OPEN or PENDING and past their due-by on the
37	 * sheet's today, as each shows it) — and the sheet's totals of them (the due-total and overdue-total
38	 * leave out the single highest and lowest person's figure when three or more people have one; a
39	 * due-total of n/a is no figure). A change that moves
40	 * any of them is followed in the audit by a ROLLUP line per person whose figures moved, then a TOTALS
41	 * line when the sheet's totals moved, then an ALERT line per person, in list order, whose due-total went
42	 * from at or below the sheet's alert threshold (or none) to above it: take a {@link #snapshot} before the change, and
43	 * {@link #recordSince} it after the change has recorded its own lines.
44	 */
45	@Service
46	public class RollupService {
47	
48	    /** A due-total shown when there is none. */
49	    public static final String NONE = "n/a";
50	
51	    private final PersonRepository people;
52	    private final ClaimRepository claims;
53	    private final RateChain rates;
54	    private final SheetRepository sheets;
55	    private final DatedSettings dated;
56	    private final Audit audit;
57	
58	    public RollupService(PersonRepository people, ClaimRepository claims, RateChain rates,
59	            SheetRepository sheets, DatedSettings dated, Audit audit) {
60	        this.dated = dated;
61	        this.people = people;
62	        this.claims = claims;
63	        this.rates = rates;
64	        this.sheets = sheets;
65	        this.audit = audit;
66	    }
67	
68	    /** A person's figures, as shown. */
69	    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
70	    }
71	
72	    /** The sheet's figures at one moment: each person's, in list order, and the totals. */
73	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
74	    }
75	
76	    /** The figures the sheet shows now. */
77	    @Transactional(propagation = Propagation.MANDATORY)
78	    public Snapshot snapshot(String sheetId) {
79	        return snapshot(people.findBySheetIdOrderByPositionAscIdAsc(sheetId),
80	                claims.findBySheetIdOrderByListedDescIdDesc(sheetId), live(sheetId));
81	    }
82	
83	    /** The figures a sheet shows on {@code basis}, from {@code everyone} on it, in list order, and their
84	     * claims {@code all}: as {@link #snapshot(String)} works them out for the sheet as it stands. */
85	    public Snapshot snapshot(List<Person> everyone, List<Claim> all, Basis basis) {
86	        LocalDate today = basis.today();
87	        BigDecimal cap = basis.cap();
88	        Map<Long, Figures> figures = new LinkedHashMap<>();
89	        BigDecimal claimedTotal = zero();
90	        List<BigDecimal> dueFigures = new ArrayList<>();
91	        List<BigDecimal> overdueFigures = new ArrayList<>();
92	        for (Person person : everyone) {
93	            BigDecimal claimed = zero();
94	            BigDecimal due = zero();
95	            BigDecimal overdue = zero();
96	            boolean any = false;
97	            for (Claim claim : all) {
98	                if (!claim.getPersonId().equals(person.getId())) continue;
99	                if (countsClaimed(claim, person, today) && !claim.isCorrection()) claimed = claimed.add(claim.getAmount());
100	                if (!countsLive(claim, person, today)) continue;
101	                BigDecimal figure = shownOf(claim, person, basis);
102	                if (figure == null) continue;
103	                if (isOverdue(claim, basis)) overdue = overdue.add(figure);
104	                due = due.add(figure);
105	                any = true;
106	            }
107	            due = cappedOf(due, cap);
108	            boolean rated = today != null && basis.rateInForce(person.gradeOn(today), today).isPresent();
109	            claimedTotal = claimedTotal.add(claimed);
110	            overdueFigures.add(overdue);
111	            if (any || rated) dueFigures.add(due);
112	            figures.put(person.getId(), new Figures(person.getName(), text(claimed), any || rated ? text(due) : NONE,
113	                    text(overdue)));
114	        }
115	        return new Snapshot(figures, text(claimedTotal), text(trimmedSum(dueFigures)), text(trimmedSum(overdueFigures)));
116	    }
117	
118	    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
119	    static BigDecimal trimmedSum(List<BigDecimal> figures) {
120	        BigDecimal sum = figures.stream().reduce(zero(), BigDecimal::add);
121	        if (figures.size() < 3) return sum;
122	        return sum.subtract(Collections.max(figures)).subtract(Collections.min(figures));
123	    }
124	
125	    /** Record the ROLLUP and TOTALS lines for the figures that moved since {@code before}. */
126	    @Transactional(propagation = Propagation.MANDATORY)
127	    public void recordSince(String sheetId, String user, Snapshot before) {
128	        Snapshot after = snapshot(sheetId);
129	        after.people().forEach((id, now) -> {
130	            Figures then = before.people().get(id);
131	            if (then != null && then.claimed().equals(now.claimed()) && then.dueTotal().equals(now.dueTotal())
132	                    && then.overdueTotal().equals(now.overdueTotal())) return;
133	            audit.change("ROLLUP", sheetId, user, "person=" + now.name(), "claimed=" + now.claimed(),
134	                    "due-total=" + now.dueTotal(), "overdue-total=" + now.overdueTotal());
135	        });
136	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
137	                || !Objects.equals(before.dueTotal(), after.dueTotal())
138	                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
139	            audit.change("TOTALS", sheetId, user, "claimed-total=" + after.claimedTotal(),
140	                    "due-total=" + after.dueTotal(), "overdue-total=" + after.overdueTotal());
141	        }
142	        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
143	        if (threshold == null) return;
144	        after.people().forEach((id, now) -> {
145	            Figures then = before.people().get(id);
146	            if (above(now.dueTotal(), threshold) && (then == null || !above(then.dueTotal(), threshold))) {
147	                audit.change("ALERT", sheetId, user, "name=" + now.name(), "due-total=" + now.dueTotal());
148	            }
149	        });
150	    }
151	
152	    /** Whether a due-total as shown is above the threshold (n/a never is). */
153	    private static boolean above(String dueTotal, BigDecimal threshold) {
154	        return !NONE.equals(dueTotal) && new BigDecimal(dueTotal).compareTo(threshold) > 0;
155	    }
156	
157	    /** Whether the claim is overdue on {@code basis}: OPEN or PENDING, not deferred on its today, and
158	     * overdue from a date before it (its due-by plus any grace, see {@link Basis#overdueFrom}). */
159	    public static boolean isOverdue(Claim claim, Basis basis) {
160	        LocalDate today = basis.today();
161	        return claim.getStatus().isOpen() && today != null && claim.getDueBy() != null
162	                && !claim.isDeferredOn(today) && basis.overdueFrom(claim).isBefore(today);
163	    }
164	
165	    /** A due-total as shown: at most {@code cap}, when there is one. */
166	    public static BigDecimal cappedOf(BigDecimal due, BigDecimal cap) {
167	        return cap == null ? due : due.min(cap);
168	    }
169	
170	    /** Whether the claim counts in the live totals on the sheet's {@code today}: OPEN, PENDING or
171	     * SETTLED, but not an OPEN claim deferred on {@code today}, nor OPEN or PENDING when its person's
172	     * retirement date is reached on {@code today} and no statement binds it. A hold, the person's or the
173	     * claim's own, does not take it out. */
174	    public static boolean countsLive(Claim claim, Person person, LocalDate today) {
175	        return countsAs(claim, claim.getStatus(), person, today);
176	    }
177	
178	    /** Whether the claim counts in what its person has claimed on the sheet's {@code today}: as it counts in
179	     * the live totals (see {@link #countsLive}). */
180	    public static boolean countsClaimed(Claim claim, Person person, LocalDate today) {
181	        return countsLive(claim, person, today);
182	    }
183	
184	    /** Whether the claim would count in the live totals on the sheet's {@code today} were its status
185	     * {@code status} (see {@link #countsLive}). */
186	    public static boolean countsAs(Claim claim, ClaimStatus status, Person person, LocalDate today) {
187	        if (!status.counts()) return false;
188	        if (!status.isOpen()) return true;
189	        if (claim.isDeferredOn(today)) return false;
190	        return claim.isStated() || !person.isRetiredOn(today);
191	    }
192	
193	    /** What a sheet's figures are worked out from: its today, the policy date, rates and dated settings in
194	     * force, and its claims. {@link #live} is the sheet as it stands; a sheet as it stood on an earlier
195	     * date gives its own. */
196	    public interface Basis {
197	
198	        /** The sheet's today; null when there is no sheet. */
199	        LocalDate today();
200	
201	        /** The policy date in force (see {@link Sheet#policyDateInForce()}); null when there is no sheet. */
202	        LocalDate policyDateInForce();
203	
204	        /** The grade's rate in force on the date (see {@link RateRepository#findInForce}), or else the
205	         * nearest parent sheet's (see {@link RateChain}). */
206	        Optional<Rate> rateInForce(String grade, LocalDate date);
207	
208	        /** The grade's rate in force on the date for the claim (see {@link RateRepository#inForce(java.util.List,
209	         * String, LocalDate, long)}): a rate saved forward-only after the claim was added does not apply to it. */
210	        Optional<Rate> rateFor(Claim claim, String grade, LocalDate date);
211	
212	        /** The floor in force on the date; 0.00 when there is no sheet. */
213	        BigDecimal floorOn(LocalDate date);
214	
215	        /** The late percent in force on the date. */
216	        BigDecimal latePctOn(LocalDate date);
217	
218	        /** The cap in force on the sheet's today; null when there is none. */
219	        BigDecimal cap();
220	
221	        /** The person's claim with the number. */
222	        Optional<Claim> claimNumbered(Long personId, String number);
223	
224	        /** The person with the id. */
225	        Optional<Person> personOf(Long personId);
226	
227	        /** The grade's grace days in force on the date; null when it has none then. */
228	        Integer graceOn(String grade, LocalDate date);
229	
230	        /** The rounding mode in force on the date; null when there is none then. */
231	        RoundingMode roundingOn(LocalDate date);
232	
233	        /** The date a claim's lateness counts from: its due-by plus the grace days in force on the claim's
234	         * date of its person's grade in force then (its due-by when that grade has none). */
235	        default LocalDate overdueFrom(Claim claim) {
236	            LocalDate dueBy = claim.getDueBy();
237	            if (dueBy == null) return null;
238	            Integer grace = personOf(claim.getPersonId()).map(p -> p.gradeOn(claim.getDate()))
239	                    .map(grade -> graceOn(grade, claim.getDate())).orElse(null);
240	            return grace == null ? dueBy : dueBy.plusDays(grace);
241	        }
242	    }
243	
244	    /** The sheet as it stands. */
245	    public Basis live(String sheetId) {
246	        return new Basis() {
247	            private Sheet sheet() {
248	                return sheets.findById(sheetId).orElse(null);
249	            }
250	
251	            @Override
252	            public LocalDate today() {
253	                Sheet sheet = sheet();
254	                return sheet == null ? null : sheet.getToday();
255	            }
256	
257	            @Override
258	            public LocalDate policyDateInForce() {
259	                Sheet sheet = sheet();
260	                return sheet == null ? null : sheet.policyDateInForce();
261	            }
262	
263	            @Override
264	            public Optional<Rate> rateInForce(String grade, LocalDate date) {
265	                return rates.inForce(sheetId, grade, date);
266	            }
267	
268	            @Override
269	            public Optional<Rate> rateFor(Claim claim, String grade, LocalDate date) {
270	                return rates.inForce(sheetId, grade, date, claim.addedMark());
271	            }
272	
273	            @Override
274	            public BigDecimal floorOn(LocalDate date) {
275	                return sheet() == null ? zero() : dated.floorOn(sheetId, date);
276	            }
277	
278	            @Override
279	            public BigDecimal latePctOn(LocalDate date) {
280	                return dated.latePctOn(sheetId, date);
281	            }
282	
283	            @Override
284	            public BigDecimal cap() {
285	                return sheet() == null ? null : dated.cap(sheetId);
286	            }
287	
288	            @Override
289	            public Optional<Claim> claimNumbered(Long personId, String number) {
290	                return claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, number);
291	            }
292	
293	            @Override
294	            public Optional<Person> personOf(Long personId) {
295	                return people.findById(personId);
296	            }
297	
298	            @Override
299	            public Integer graceOn(String grade, LocalDate date) {
300	                return dated.gradeGraceOn(sheetId, grade, date);
301	            }
302	
303	            @Override
304	            public RoundingMode roundingOn(LocalDate date) {
305	                return dated.roundingOn(sheetId, date);
306	            }
307	        };
308	    }
309	
310	    /** {@code base}, but with the grade's rate {@code pct} in force on every date. */
311	    public static Basis withRate(Basis base, String grade, BigDecimal pct) {
312	        Rate rate = new Rate(null, grade, null, null, pct);
313	        return new Basis() {
314	            @Override
315	            public LocalDate today() {
316	                return base.today();
317	            }
318	
319	            @Override
320	            public LocalDate policyDateInForce() {
321	                return base.policyDateInForce();
322	            }
323	
324	            @Override
325	            public Optional<Rate> rateInForce(String g, LocalDate date) {
326	                return grade.equals(g) ? Optional.of(rate) : base.rateInForce(g, date);
327	            }
328	
329	            @Override
330	            public Optional<Rate> rateFor(Claim claim, String g, LocalDate date) {
331	                return grade.equals(g) ? Optional.of(rate) : base.rateFor(claim, g, date);
332	            }
333	
334	            @Override
335	            public BigDecimal floorOn(LocalDate date) {
336	                return base.floorOn(date);
337	            }
338	
339	            @Override
340	            public BigDecimal latePctOn(LocalDate date) {
341	                return base.latePctOn(date);
342	            }
343	
344	            @Override
345	            public BigDecimal cap() {
346	                return base.cap();
347	            }
348	
349	            @Override
350	            public Optional<Claim> claimNumbered(Long personId, String number) {
351	                return base.claimNumbered(personId, number);
352	            }
353	
354	            @Override
355	            public Optional<Person> personOf(Long personId) {
356	                return base.personOf(personId);
357	            }
358	
359	            @Override
360	            public Integer graceOn(String g, LocalDate date) {
361	                return base.graceOn(g, date);
362	            }
363	
364	            @Override
365	            public RoundingMode roundingOn(LocalDate date) {
366	                return base.roundingOn(date);
367	            }
368	        };
369	    }
370	
371	    /** The person's due-total on {@code basis} from those of {@code theirs} that count on its today (see
372	     * {@link #countsLive}): the sum of what is due on them as each shows it, at most the cap; null (n/a)
373	     * when none has a figure and no rate of their grade is in force on its today. */
374	    public BigDecimal dueTotalOf(List<Claim> theirs, Person person, Basis basis) {
375	        LocalDate today = basis.today();
376	        BigDecimal due = zero();
377	        boolean any = false;
378	        for (Claim claim : theirs) {
379	            if (!countsLive(claim, person, today)) continue;
380	            BigDecimal figure = shownOf(claim, person, basis);
381	            if (figure == null) continue;
382	            due = due.add(figure);
383	            any = true;
384	        }
385	        boolean rated = today != null && basis.rateInForce(person.gradeOn(today), today).isPresent();
386	        return any || rated ? cappedOf(due, basis.cap()) : null;
387	    }
388	
389	    /** Whether the claim shows the figure fixed when it was settled at a rate: it is SETTLED, or was
390	     * voided once settled, and has one. */
391	    private static boolean frozen(Claim claim) {
392	        return claim.getSettledDue() != null
393	                && (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID);
394	    }
395	
396	    /** The figure the claim shows and totals now: what was fixed when it was settled at a rate (kept
397	     * once it is voided);
398	     * otherwise the figure a statement bound it to (PENDING or not); otherwise what is due on it at its person's rate.
399	     * Null when it has no figure. */
400	    public BigDecimal figureOf(Claim claim, Person person) {
401	        return figureOf(claim, person, live(claim.getSheetId()));
402	    }
403	
404	    /** The figure the claim shows on {@code basis} (see {@link #figureOf(Claim, Person)}). */
405	    public BigDecimal figureOf(Claim claim, Person person, Basis basis) {
406	        if (frozen(claim)) return claim.getSettledDue();
407	        if (claim.isStated()) return claim.getStatedDue();
408	        return dueOf(claim, person, basis);
409	    }
410	
411	    /** What is due on the claim as it shows and totals now: what was fixed when it was settled at a
412	     * rate; otherwise, while a statement binds it, what was due on it as it showed then, late charge
413	     * included; otherwise its live due on its figure (see {@link #liveDueOf}); null when it has no figure. */
414	    public BigDecimal shownOf(Claim claim, Person person) {
415	        return shownOf(claim, person, live(claim.getSheetId()));
416	    }
417	
418	    /** What is due on the claim as it shows on {@code basis} (see {@link #shownOf(Claim, Person)}). */
419	    public BigDecimal shownOf(Claim claim, Person person, Basis basis) {
420	        BigDecimal figure = figureOf(claim, person, basis);
421	        if (frozen(claim)) return figure;
422	        if (claim.isStated() && claim.getStatedShown() != null) return claim.getStatedShown();
423	        return liveDueOf(claim, figure, basis);
424	    }
425	
426	    /** The live due on the claim whose figure (at its rate, or as a statement bound it) is
427	     * {@code figure}: that figure, at least the sheet's floor in force on the claim's date, plus the late
428	     * charge worked out on that floored figure (see {@link #lateChargeOf}); a correction has neither floor
429	     * nor charge. Null when {@code figure} is. */
430	    public BigDecimal liveDueOf(Claim claim, BigDecimal figure) {
431	        return liveDueOf(claim, figure, live(claim.getSheetId()));
432	    }
433	
434	    private BigDecimal liveDueOf(Claim claim, BigDecimal figure, Basis basis) {
435	        if (figure == null) return null;
436	        if (claim.isCorrection()) return figure;
437	        BigDecimal floored = floored(claim, figure, basis);
438	        return floored.add(lateChargeOf(claim, floored, basis));
439	    }
440	
441	    /** The figure a statement taken on {@code basis} binds the claim to: what was fixed when it was
442	     * settled at a rate; otherwise its figure (see {@link #figureOf(Claim, Person, Basis)}), at least the
443	     * sheet's floor in force on its date (a correction has no floor). Null when it has no figure. */
444	    public BigDecimal statedFigureOf(Claim claim, Person person, Basis basis) {
445	        BigDecimal figure = figureOf(claim, person, basis);
446	        if (figure == null || frozen(claim) || claim.isCorrection()) return figure;
447	        return floored(claim, figure, basis);
448	    }
449	
450	    /** {@code due}, at least the sheet's floor in force on the claim's date. */
451	    private static BigDecimal floored(Claim claim, BigDecimal due, Basis basis) {
452	        return due.max(basis.floorOn(claim.getDate()));
453	    }
454	
455	    /** The late charge on an OPEN or PENDING claim whose figure is {@code figure}: for every full 30 days the claim is overdue (past its due-by, fixed when it was added, plus
456	     * any grace of its grade (see {@link Basis#overdueFrom}), on the sheet's today), the sheet's late percent
457	     * in force on that boundary date (that date plus 30, 60, 90 ... days) of that figure plus the charges of the boundaries before it (compounding), rounded to two decimals as the claim rounds, the charges added up (a boundary whose percent is 0.00 adds nothing) (see {@link #roundingOf}); 0.00 on a claim not OPEN or
458	     * PENDING, or not overdue (a deferred claim is not), on a correction and on a waived claim. A claim a statement binds shows the charge it had then instead (see {@link #shownOf}). */
459	    public BigDecimal lateChargeOf(Claim claim, BigDecimal figure) {
460	        return lateChargeOf(claim, figure, live(claim.getSheetId()));
461	    }
462	
463	    private BigDecimal lateChargeOf(Claim claim, BigDecimal figure, Basis basis) {
464	        if (!claim.getStatus().isOpen()) return zero();
465	        return overdueChargeOf(claim, figure, basis);
466	    }
467	
468	    /** What would be due on the claim now were it an OPEN claim bound by no statement: its due at its
469	     * person's rate (see {@link #dueOf}), at least the sheet's floor in force on its date, plus the late
470	     * charge it would have then on that floored figure (a correction has neither); null when it would
471	     * have no figure. */
472	    public BigDecimal openShownOf(Claim claim, Person person) {
473	        Basis basis = live(claim.getSheetId());
474	        BigDecimal figure = dueOf(claim, person, basis);
475	        if (figure == null || claim.isCorrection()) return figure;
476	        BigDecimal floored = floored(claim, figure, basis);
477	        return floored.add(overdueChargeOf(claim, floored, basis));
478	    }
479	
480	    /** The late charge on a claim whose figure is {@code figure}, whatever its status (see {@link #lateChargeOf}). */
481	    private BigDecimal overdueChargeOf(Claim claim, BigDecimal figure, Basis basis) {
482	        if (claim.isCorrection() || claim.isWaived()) return zero();
483	        LocalDate today = basis.today();
484	        if (today == null || claim.isDeferredOn(today)) return zero();
485	        LocalDate from = basis.overdueFrom(claim);
486	        long periods = Math.max(0, ChronoUnit.DAYS.between(from, today)) / 30;
487	        RoundingMode rounding = roundingOf(claim, basis);
488	        BigDecimal charge = zero();
489	        for (long k = 1; k <= periods; k++) {
490	            BigDecimal pct = basis.latePctOn(from.plusDays(30 * k));
491	            if (pct.signum() == 0) continue;
492	            charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
493	        }
494	        return charge;
495	    }
496	
497	    /** What is due on the claim at its person's rate in force on the claim's date: amount times pct,
498	     * divided by 100, rounded to two decimals as the claim rounds (see {@link #roundingOf}) — the rate
499	     * figure alone, before any late charge or floor (see {@link #liveDueOf}); null when no
500	     * rate of the grade in force for them on the claim's date applies then. */
501	    public BigDecimal dueOf(Claim claim, Person person) {
502	        return dueOf(claim, person, live(claim.getSheetId()));
503	    }
504	
505	    private BigDecimal dueOf(Claim claim, Person person, Basis basis) {
506	        RoundingMode rounding = roundingOf(claim, basis);
507	        return basis.rateFor(claim, person.gradeOn(claim.getDate()), claim.getDate())
508	                .map(Rate::getPct)
509	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
510	                .orElse(null);
511	    }
512	
513	    /** How the claim's live figures round: by the rounding mode in force on its date when there is one;
514	     * else half up when it is dated before the sheet's policy date in force, half to even when on or
515	     * after it. A correction rounds by the date of the claim it corrects. */
516	    private static RoundingMode roundingOf(Claim claim, Basis basis) {
517	        LocalDate dated = claim.getDate();
518	        if (claim.isCorrection() && claim.getCorrects() != null) {
519	            dated = basis.claimNumbered(claim.getPersonId(), claim.getCorrects()).map(Claim::getDate).orElse(dated);
520	        }
521	        RoundingMode mode = basis.roundingOn(dated);
522	        if (mode != null) return mode;
523	        LocalDate policyDate = basis.policyDateInForce();
524	        if (policyDate == null) return RoundingMode.HALF_EVEN;
525	        return dated.isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
526	    }
527	
528	    private static BigDecimal zero() {
529	        return BigDecimal.ZERO.setScale(2);
530	    }
531	
532	    private static String text(BigDecimal value) {
533	        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
534	    }
535	}
