    @Query("SELECT r FROM Rate r WHERE r.sheetId = :sheetId AND r.grade = :grade AND r.from IS NULL")
    Optional<Rate> findUndated(String sheetId, String grade);

    Optional<Rate> findBySheetIdAndGradeAndFrom(String sheetId, String grade, LocalDate from);

    /** The grade's rate in force on {@code date}: the one with the latest from-date on or before it, or
     * the one with no from-date when none has; empty when no rate applies yet, or when that rate's
     * to-date is before {@code date} (an earlier rate does not apply again). */
    default Optional<Rate> findInForce(String sheetId, String grade, LocalDate date) {
        return inForce(findBySheetIdAndGrade(sheetId, grade), grade, date);
    }

    /** The grade's rate in force on {@code date} among {@code rates} (see {@link #findInForce}). */
    static Optional<Rate> inForce(List<Rate> rates, String grade, LocalDate date) {
        return rates.stream()
                .filter(r -> r.getGrade().equals(grade))
                .filter(r -> r.getFrom() == null || !r.getFrom().isAfter(date))
                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> r.getTo() == null || !r.getTo().isBefore(date));
    }

    /** The grade's rate in force on {@code date} among {@code rates} for a claim added at {@code added}
     * (see {@link Rate#forClaim}): a rate saved forward-only after the claim was added is passed over for
     * it, as are the newer versions of a rate saved so. */
    static Optional<Rate> inForce(List<Rate> rates, String grade, LocalDate date, long added) {
        return inForce(rates.stream().filter(r -> r.getGrade().equals(grade))
                .flatMap(r -> r.forClaim(added).stream()).toList(), grade, date);
    }
}
package net.officefloor.hq.app.person;


/**
 * A person on a sheet: a name and a dated grade (A, B or C): each grade they are given is in force
 * from its from-date, the first from the beginning of time (see {@link #gradeOn}). The name is kept without the spaces around
 * it and is unique on the sheet without regard to case, compared through its {@link #keyOf key}.
 */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "name_key", nullable = false)
    private String nameKey;

    /** The grades the person has been given, at most one per from-date. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<PersonGrade> grades = new ArrayList<>();

    /** The date the person is retired from; null while they are not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The person's past retirements, each ended by an unretire. Loaded by a sub-select, so it loads
     * eagerly beside the grades. */
    @ElementCollection(fetch = FetchType.EAGER)
    @Fetch(FetchMode.SUBSELECT)
    @CollectionTable(name = "person_retirement", joinColumns = @JoinColumn(name = "person_id"))
    private List<PersonRetirement> retirements = new ArrayList<>();

    /** The holds the person has been put on: while one is in force the person gets no cut of a pool; their
     * claims still count in every total. The same hold may be put on more than once. Loaded by
     * a sub-select, so it loads eagerly beside the grades. */
    @ElementCollection(fetch = FetchType.EAGER)
    @Fetch(FetchMode.SUBSELECT)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<PersonHold> holds = new ArrayList<>();

    /** The other names the person goes by; each unique on the sheet among its names and aliases. Loaded
     * by a sub-select, so it loads eagerly beside the grades. */
    @ElementCollection(fetch = FetchType.EAGER)
    @Fetch(FetchMode.SUBSELECT)
    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
    private List<PersonAlias> aliases = new ArrayList<>();

    /** The person's own terms in days, in place of their grade's and the sheet's; null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** The person's own terms dated from a day, at most one per from-date, in place of {@link #terms}
     * from then. Loaded by a sub-select, so it loads eagerly beside the grades. */
    @ElementCollection(fetch = FetchType.EAGER)
    @Fetch(FetchMode.SUBSELECT)
    @CollectionTable(name = "person_terms", joinColumns = @JoinColumn(name = "person_id"))
    private List<PersonTerms> datedTerms = new ArrayList<>();

    /** The person's contact, without surrounding spaces and in lower case, unique on the sheet; null
     * when they have none. */
    @Column(name = "contact")
    private String contact;

    /** The person's tags: trimmed, lower-cased, without repeats, sorted and comma separated; null when
     * they have none (see {@link net.officefloor.hq.app.claim.Claim#tagsOf}). */
    @Column(name = "tags")
    private String tags;

    /** The sheet the person was transferred from; null when they were not transferred. */
    @Column(name = "origin_sheet_id")
    private String originSheetId;

    /** The sheet's today when a transfer brought the person to it; null when they did not arrive by
     * transfer. */
    @Column(name = "arrived_on")
    private LocalDate arrivedOn;

    /** The reason a steward flagged the person for; null when never flagged. */
    @Column(name = "flag_reason")
    private String flagReason;

    /** The last day the person's flag is in force; null when never flagged. */
    @Column(name = "flag_until")
    private LocalDate flagUntil;

    /** The user who may approve or reject the person's PENDING claims as a steward may; null when
     * they have none. */
    @Column(name = "approver")
    private String approver;

    /** The person's place in the sheet's list: people are listed by it, lowest first. */
    @Column(name = "list_position", nullable = false)
    private Long position;

    /** Raised each time the person is saved. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        setName(name);
        this.grades.add(new PersonGrade(grade, null));
    }

    /** The form of a name that is unique on a sheet: without surrounding spaces, in lower case. */
    public static String keyOf(String name) {
        return name.trim().toLowerCase(Locale.ROOT);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name.trim();
        this.nameKey = keyOf(name);
    }

    /** A copy of the person on the sheet {@code sheetId}: the same name, every grade they were given
     * (with its from-date), their terms, contact and aliases, noting this sheet as the one they came
     * from and {@code arrivedOn} as the day they arrived; nothing else of theirs comes with it. */
    public Person transferredTo(String sheetId, LocalDate arrivedOn) {
        Person copy = new Person();
        copy.sheetId = sheetId;
        copy.originSheetId = this.sheetId;
        copy.arrivedOn = arrivedOn;
        copy.setName(name);
        grades.forEach(g -> copy.grades.add(new PersonGrade(g.getGrade(), g.getFrom())));
        copy.terms = terms;
        datedTerms.forEach(t -> copy.datedTerms.add(new PersonTerms(t.getTerms(), t.getFrom())));
        copy.contact = contact;
        copy.tags = tags;
        aliases.forEach(a -> copy.aliases.add(new PersonAlias(a.getAlias())));
        return copy;
    }

    /** A copy of the person on the sheet {@code sheetId}, a clone of theirs: the same name, place in the
     * list, every grade (with its from-date), terms, contact, aliases, holds, retirement and past
     * retirements. */
    public Person clonedTo(String sheetId) {
        Person copy = new Person();
        copy.sheetId = sheetId;
        copy.setName(name);
        grades.forEach(g -> copy.grades.add(new PersonGrade(g.getGrade(), g.getFrom())));
        copy.retiredFrom = retiredFrom;
        retirements.forEach(r -> copy.retirements.add(new PersonRetirement(r.getFrom(), r.getTo())));
        holds.forEach(h -> copy.holds.add(new PersonHold(h.getFrom(), h.getTo())));
        aliases.forEach(a -> copy.aliases.add(new PersonAlias(a.getAlias())));
        copy.terms = terms;
        datedTerms.forEach(t -> copy.datedTerms.add(new PersonTerms(t.getTerms(), t.getFrom())));
        copy.contact = contact;
        copy.tags = tags;
        copy.flagReason = flagReason;
        copy.flagUntil = flagUntil;
        copy.approver = approver;
        copy.position = position;
        return copy;
    }

    /** The grades the person has been given, by from-date (the one with none first). */
    public List<PersonGrade> getGrades() {
        return grades.stream()
                .sorted(Comparator.comparing(PersonGrade::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** Gives the person {@code grade} from {@code from}, in place of one given from the same date. */
    public void setGrade(String grade, LocalDate from) {
        grades.removeIf(g -> from.equals(g.getFrom()));
        grades.add(new PersonGrade(grade, from));
    }

    /** The grade in force on {@code date}: the one with the latest from-date on or before it, or the
     * first one given when none has; the latest given when {@code date} is null. */
    public String gradeOn(LocalDate date) {
        PersonGrade best = null;
        for (PersonGrade g : getGrades()) {
            if (date != null && g.getFrom() != null && g.getFrom().isAfter(date)) continue;
            best = g;
        }
        return best == null ? null : best.getGrade();
    }

    public Integer getTerms() {
        return terms;
    }

    /** Gives the person {@code terms} (none when null) from the beginning of time, keeping their dated terms. */
    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    /** The person's dated terms, by from-date. */
    public List<PersonTerms> getDatedTerms() {
        return datedTerms.stream().sorted(Comparator.comparing(PersonTerms::getFrom)).toList();
    }

    /** Gives the person {@code terms} (none when null) from {@code from}, in place of those given from the same date. */
    public void setTerms(Integer terms, LocalDate from) {
        datedTerms.removeIf(t -> from.equals(t.getFrom()));
        datedTerms.add(new PersonTerms(terms, from));
    }

    /** The person's own terms in force on {@code date}: those with the latest from-date on or before it,
     * else their undated terms; null when they have none then. */
    public Integer termsOn(LocalDate date) {
        Integer in = terms;
        for (PersonTerms t : getDatedTerms()) {
            if (date != null && t.getFrom().isAfter(date)) break;
            in = t.getTerms();
        }
        return in;
    }

    /** The form a contact is kept in: without surrounding spaces, in lower case; null for a blank one. */
    public static String contactOf(String contact) {
        if (contact == null || contact.isBlank()) return null;
        return contact.trim().toLowerCase(Locale.ROOT);
    }

    public String getContact() {
        return contact;
    }

    /** Gives the person {@code contact} (none when blank), kept in its {@link #contactOf stored form}. */
    public void setContact(String contact) {
        this.contact = contactOf(contact);
    }

    /** The person's tags, sorted; empty when they have none. */
    public List<String> getTags() {
        return tags == null ? List.of() : List.of(tags.split(","));
    }

    /** Gives the person the tags, as {@link net.officefloor.hq.app.claim.Claim#tagsOf} makes them (none
     * when null). */
    public void setTags(String tags) {
        this.tags = tags;
    }

    /** The person's aliases, sorted as names are compared. */
    public List<String> getAliases() {
        return aliases.stream()
                .sorted(Comparator.comparing(PersonAlias::getAliasKey).thenComparing(PersonAlias::getAlias))
                .map(PersonAlias::getAlias)
                .toList();
    }

    /** Gives the person the alias {@code alias}, kept without the spaces around it. */
    public void addAlias(String alias) {
        aliases.add(new PersonAlias(alias));
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    /** Retired as soon as a retirement date is set, whatever the date. */
    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether the person's retirement date is reached on {@code today}: on or after it. */
    public boolean isRetiredOn(LocalDate today) {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom);
    }

    /** The person's past retirements, by from-date. */
    public List<PersonRetirement> getRetirements() {
        return retirements.stream()
                .sorted(Comparator.comparing(PersonRetirement::getFrom).thenComparing(PersonRetirement::getTo))
                .toList();
    }

    /** Ends the person's retirement on {@code on}, keeping it as a past retirement; they are no longer retired. */
    public void unretire(LocalDate on) {
        retirements.add(new PersonRetirement(retiredFrom, on));
        retiredFrom = null;
    }

    /** The holds the person has been put on, by from-date. */
    public List<PersonHold> getHolds() {
        return holds.stream()
                .sorted(Comparator.comparing(PersonHold::getFrom)
                        .thenComparing(PersonHold::getTo, Comparator.nullsLast(Comparator.naturalOrder())))
                .toList();
    }

    /** Puts the person on {@code hold}. */
    public void addHold(PersonHold hold) {
        holds.add(hold);
    }

    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** Whether {@code date} falls within any of the person's holds. */
    public boolean isHeldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    /** Refuses a claim dated {@code date} when it falls after the person's retirement date, or after the
     * from-date and before the to-date of a past retirement. */
    public void requireClaimable(LocalDate date) {
        if ((retiredFrom != null && date.isAfter(retiredFrom)) || retirements.stream().anyMatch(r -> r.excludes(date))) {
            throw new PersonRetiredException();
        }
    }

    /** The sheet the person was transferred from; null when they were not transferred. */
    public String getOriginSheetId() {
        return originSheetId;
    }

    /** The sheet's today when a transfer brought the person to it; null when they did not arrive by
     * transfer. */
    public LocalDate getArrivedOn() {
        return arrivedOn;
    }

    /** Flags the person with {@code reason} until {@code until}, in place of any flag they had. */
    public void flag(String reason, LocalDate until) {
        this.flagReason = reason;
        this.flagUntil = until;
    }

    public String getFlagReason() {
        return flagReason;
    }

    public LocalDate getFlagUntil() {
        return flagUntil;
    }

    /** Whether the person's flag is in force on {@code today}: on or before its until date. */
    public boolean isFlaggedOn(LocalDate today) {
        return flagReason != null && flagUntil != null && today != null && !today.isAfter(flagUntil);
    }

    /** The reason of the person's flag in force on {@code today}; null when none is. */
    public String flagOn(LocalDate today) {
        return isFlaggedOn(today) ? flagReason : null;
    }

    public String getApprover() {
        return approver;
    }

    public void setApprover(String approver) {
        this.approver = approver;
    }

    public Long getPosition() {
        return position;
    }

    public void setPosition(Long position) {
        this.position = position;
    }

    public long getVersion() {
        return version;
    }
}
package net.officefloor.hq.app.settings;


/** The values in force of a sheet's dated settings: on a date, the value recorded with the latest
 * from-date on or before it, and before every from-date the sheet's starting value (floor 1.00, late
 * percent 0.00, terms 14 days; no clerk limit, no grade's own clerk limit, no cap, no proof threshold, no grade's own proof threshold, no note threshold, no review threshold, no grade's own terms and no grade's grace days). A claim's floor, late
 * percent, terms, proof threshold, note threshold and review threshold are those in force on its date; the clerk limit and the cap those on the sheet's
 * today. */
@Service
public class DatedSettings {

    public static final String FLOOR = "floor";
    public static final String LATE_PCT = "late-pct";
    public static final String TERMS = "terms";
    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String CAP = "cap";
    public static final String PROOF_THRESHOLD = "proof-threshold";
    public static final String NOTE_THRESHOLD = "note-threshold";
    public static final String REVIEW_THRESHOLD = "review-threshold";
    public static final String GRACE = "grace";
    public static final String ROUNDING = "rounding";
    public static final String HALF_UP = "half-up";
    public static final String HALF_EVEN = "half-even";

    public static final BigDecimal FLOOR_START = new BigDecimal("1.00");
    public static final BigDecimal LATE_PCT_START = new BigDecimal("0.00");
    public static final int TERMS_START = 14;

    private final SheetSettingRepository settings;
    private final SheetRepository sheets;

    public DatedSettings(SheetSettingRepository settings, SheetRepository sheets) {
        this.settings = settings;
        this.sheets = sheets;
    }

    /** The key a grade's own terms are kept under. */
    public static String gradeTermsKey(String grade) {
        return TERMS + "-" + grade;
    }

    /** The key a grade's own proof threshold is kept under. */
    public static String gradeProofThresholdKey(String grade) {
        return PROOF_THRESHOLD + "-" + grade;
    }

    /** The key a grade's own clerk limit is kept under. */
    public static String gradeClerkLimitKey(String grade) {
        return CLERK_LIMIT + "-" + grade;
    }

    /** The key a grade's grace days are kept under. */
    public static String gradeGraceKey(String grade) {
        return GRACE + "-" + grade;
    }

    /** Every value recorded for the key, oldest from-date first. */
    @Transactional(readOnly = true)
    public List<SheetSetting> history(String sheetId, String key) {
        return settings.findBySheetIdAndKeyOrderByFromAsc(sheetId, key);
    }

    @Transactional(readOnly = true)
    public BigDecimal floorOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, FLOOR, date).map(BigDecimal::new).orElse(FLOOR_START);
    }

    @Transactional(readOnly = true)
    public BigDecimal latePctOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, LATE_PCT, date).map(BigDecimal::new).orElse(LATE_PCT_START);
    }

    /** The sheet's own terms in force on the date, in days. */
    @Transactional(readOnly = true)
    public int termsOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, TERMS, date).map(Integer::valueOf).orElse(TERMS_START);
    }

    /** The grade's own terms in force on the date, in days; null when it uses the sheet's terms then. */
    @Transactional(readOnly = true)
    public Integer gradeTermsOn(String sheetId, String grade, LocalDate date) {
        return valueOn(sheetId, gradeTermsKey(grade), date).map(Integer::valueOf).orElse(null);
    }

    /** The terms a claim dated {@code date} of a person of {@code grade} is due by: the grade's own in
     * force then, or else the sheet's in force then. */
    @Transactional(readOnly = true)
    public int termsFor(String sheetId, String grade, LocalDate date) {
        Integer own = grade == null ? null : gradeTermsOn(sheetId, grade, date);
        return own != null ? own : termsOn(sheetId, date);
    }

    /** The grade's grace days in force on the date: a claim of a person of the grade then, dated then, is
     * overdue only once its due-by plus them is past; null when the grade has none then. */
    @Transactional(readOnly = true)
    public Integer gradeGraceOn(String sheetId, String grade, LocalDate date) {
        return grade == null ? null : valueOn(sheetId, gradeGraceKey(grade), date).map(Integer::valueOf).orElse(null);
    }

    /** The clerk limit in force on the sheet's today; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String sheetId) {
        return valueOn(sheetId, CLERK_LIMIT, today(sheetId)).map(BigDecimal::new).orElse(null);
    }

    /** The grade's own clerk limit in force on the date; null when it has none then. */
    @Transactional(readOnly = true)
    public BigDecimal gradeClerkLimitOn(String sheetId, String grade, LocalDate date) {
        return grade == null ? null : valueOn(sheetId, gradeClerkLimitKey(grade), date).map(BigDecimal::new).orElse(null);
    }

    /** The clerk limit of a claim of a person of {@code grade}: the grade's own in force on the sheet's
     * today, or else the sheet's in force then; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimitFor(String sheetId, String grade) {
        BigDecimal own = gradeClerkLimitOn(sheetId, grade, today(sheetId));
        return own != null ? own : clerkLimit(sheetId);
    }

    /** The cap in force on the sheet's today; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal cap(String sheetId) {
        return valueOn(sheetId, CAP, today(sheetId)).map(BigDecimal::new).orElse(null);
    }

    /** The proof threshold in force on the date; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal proofThresholdOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, PROOF_THRESHOLD, date).map(BigDecimal::new).orElse(null);
    }

    /** The grade's own proof threshold in force on the date; null when it has none then. */
    @Transactional(readOnly = true)
    public BigDecimal gradeProofThresholdOn(String sheetId, String grade, LocalDate date) {
        return grade == null ? null : valueOn(sheetId, gradeProofThresholdKey(grade), date).map(BigDecimal::new).orElse(null);
    }

    /** The proof threshold of a claim dated {@code date} of a person of {@code grade}: the grade's own in
     * force then, or else the sheet's in force then; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal proofThresholdFor(String sheetId, String grade, LocalDate date) {
        BigDecimal own = gradeProofThresholdOn(sheetId, grade, date);
        return own != null ? own : proofThresholdOn(sheetId, date);
    }

    /** The note threshold in force on the date; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal noteThresholdOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, NOTE_THRESHOLD, date).map(BigDecimal::new).orElse(null);
    }

    /** The review threshold in force on the date; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal reviewThresholdOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, REVIEW_THRESHOLD, date).map(BigDecimal::new).orElse(null);
    }

    /** The rounding mode recorded in force on the date, as text; null when there is none. */
    @Transactional(readOnly = true)
    public String roundingValueOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, ROUNDING, date).orElse(null);
    }

    /** The rounding mode in force on the date; null when there is none. */
    @Transactional(readOnly = true)
    public RoundingMode roundingOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, ROUNDING, date).map(DatedSettings::roundingMode).orElse(null);
    }

    /** The rounding mode a recorded rounding value names; null for any other. */
    public static RoundingMode roundingMode(String value) {
        return switch (value) {
            case HALF_UP -> RoundingMode.HALF_UP;
            case HALF_EVEN -> RoundingMode.HALF_EVEN;
            default -> null;
        };
    }

    /** The value of the key in force on the date; empty when none is recorded then, or the one
     * recorded is "none". */
    private Optional<String> valueOn(String sheetId, String key, LocalDate date) {
        return settings.findFirstBySheetIdAndKeyAndFromLessThanEqualOrderByFromDesc(sheetId, key, date)
                .map(SheetSetting::getValue);
    }

    private LocalDate today(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
    }
}

